<template>
  <div class="glossary">
    <el-card><div class="toolbar"><el-input v-model="question" clearable placeholder="查询工业口径，如：合格可用量 / 需求缺口 / 承诺版本" @keyup.enter="search"/><el-button type="primary" :loading="searching" @click="search">搜索口径</el-button></div><el-alert v-if="answer" :title="answer" type="success" :closable="false"/><el-table v-if="searched" :data="hits"><el-table-column prop="type" label="类型" width="90"/><el-table-column prop="title" label="标题" min-width="200"/><el-table-column prop="conceptCode" label="工业对象" width="170"/><el-table-column prop="content" label="定义与来源" min-width="300" show-overflow-tooltip/></el-table></el-card>
    <el-card class="dictionary"><el-tabs v-model="tab"><el-tab-pane label="工业术语" name="terms"><div class="toolbar"><el-select v-model="concept" clearable filterable placeholder="按对象筛选" @change="loadTerms"><el-option v-for="c in concepts.concepts" :key="c.code" :label="`${c.name}（${c.code}）`" :value="c.code"/></el-select><el-button v-if="canWrite" type="primary" @click="termVisible=true">新增术语</el-button></div><el-table :data="terms" v-loading="loading"><el-table-column prop="term" label="术语" min-width="180"/><el-table-column prop="conceptCode" label="所属对象" min-width="180"/><el-table-column prop="sourceProduct" label="来源系统"/><el-table-column prop="termType" label="类型"/><el-table-column prop="codeSystem" label="编码体系"/><el-table-column prop="standardCode" label="标准编码"/><el-table-column v-if="canWrite" label="操作" width="90"><template #default="{row}"><el-button type="danger" link @click="remove(row)">删除</el-button></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane label="指标定义" name="metrics"><el-alert title="指标定义与实时业务值分开管理。仅已配置并核对过的 JDBC 探针可执行实测，缺少来源时保持待接入。" type="info" :closable="false"/><el-table :data="metrics" class="metrics"><el-table-column prop="metricCode" label="指标编码" width="130"/><el-table-column prop="name" label="名称" min-width="170"/><el-table-column prop="definition" label="口径定义" min-width="230" show-overflow-tooltip/><el-table-column prop="formula" label="公式" min-width="230" show-overflow-tooltip/><el-table-column prop="owner" label="责任人" width="140"/><el-table-column label="数据来源" width="150"><template #default="{row}"><el-tag :type="row.dsCode&&row.probeSql?'success':'info'">{{ row.dsCode&&row.probeSql?'已配置探针':'待接入' }}</el-tag></template></el-table-column><el-table-column label="最近实测" width="120"><template #default="{row}">{{ values[row.metricCode]?.value ?? row.lastVal ?? '未采集' }}</template></el-table-column><el-table-column v-if="canWrite" label="操作" width="140"><template #default="{row}"><el-button link @click="editMetric(row)">编辑</el-button><el-button v-if="row.dsCode&&row.probeSql" link :loading="evaluating===row.metricCode" @click="evaluate(row)">实测</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs></el-card>
    <el-dialog v-model="termVisible" title="新增工业术语" width="520px"><el-form label-position="top"><el-form-item label="术语"><el-input v-model="termForm.term"/></el-form-item><el-form-item label="所属对象"><el-select v-model="termForm.conceptCode" filterable><el-option v-for="c in concepts.concepts" :key="c.code" :label="`${c.name}（${c.code}）`" :value="c.code"/></el-select></el-form-item><el-form-item label="来源系统"><el-input v-model="termForm.sourceProduct"/></el-form-item><el-form-item label="类型"><el-select v-model="termForm.termType"><el-option label="标准术语" value="STANDARD"/><el-option label="别名 / 方言" value="ALIAS"/></el-select></el-form-item><el-form-item label="编码体系"><el-input v-model="termForm.codeSystem"/></el-form-item><el-form-item label="标准编码"><el-input v-model="termForm.standardCode"/></el-form-item></el-form><template #footer><el-button @click="termVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveTerm">保存</el-button></template></el-dialog>
    <el-dialog v-model="metricVisible" title="工业指标口径" width="650px"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="metricForm.name"/></el-form-item><el-form-item label="口径定义"><el-input v-model="metricForm.definition" type="textarea" :rows="3"/></el-form-item><el-form-item label="公式"><el-input v-model="metricForm.formula" type="textarea" :rows="3"/></el-form-item><el-form-item label="工业对象"><el-select v-model="metricForm.conceptCode" filterable><el-option v-for="c in concepts.concepts" :key="c.code" :label="`${c.name}（${c.code}）`" :value="c.code"/></el-select></el-form-item><el-form-item label="责任人"><el-input v-model="metricForm.owner"/></el-form-item><el-form-item label="已验证的 JDBC 数据源"><el-select v-model="metricForm.dsCode" clearable><el-option v-for="d in datasources" :key="d.dsCode" :label="d.dsName" :value="d.dsCode"/></el-select></el-form-item><el-form-item label="只读 SQL 探针（配置后手动执行）"><el-input v-model="metricForm.probeSql" type="textarea" :rows="4"/></el-form-item><el-form-item label="告警阈值"><el-input-number v-model="metricForm.warnThreshold"/></el-form-item></el-form><template #footer><el-button @click="metricVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveMetric">保存口径</el-button></template></el-dialog>
  </div>
</template>
<script setup>
import {ref,reactive,computed,onMounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {listTerms as fetchTerms,createTerm,deleteTerm,listMetrics,searchGlossary,updateMetric,evaluateMetric} from '../../api/glossary'
import {listDatasources} from '../../api/datasource'
import {useConceptStore} from '../../store/concept'
import {useUserStore} from '../../store/user'
const concepts=useConceptStore(),user=useUserStore(),canWrite=computed(()=>['ADMIN','EDITOR'].includes(user.user?.role))
const tab=ref('terms'),concept=ref(''),terms=ref([]),metrics=ref([]),datasources=ref([]),loading=ref(false),saving=ref(false),question=ref(''),searching=ref(false),searched=ref(false),answer=ref(''),hits=ref([]),values=ref({}),evaluating=ref(''),termVisible=ref(false),metricVisible=ref(false)
const termForm=reactive({term:'',conceptCode:'',sourceProduct:'ForgePilot',termType:'STANDARD',codeSystem:'平台标准',standardCode:''}),metricForm=reactive({})
async function search(){if(!question.value.trim())return;searching.value=true;try{const result=await searchGlossary(question.value.trim());hits.value=result.hits||[];answer.value=result.answer||'';searched.value=true}finally{searching.value=false}}
async function loadTerms(){loading.value=true;try{terms.value=await fetchTerms(concept.value||undefined)}finally{loading.value=false}}
async function saveTerm(){if(!termForm.term.trim()||!termForm.conceptCode){ElMessage.warning('请填写术语与所属对象');return}saving.value=true;try{await createTerm({...termForm,term:termForm.term.trim()});termVisible.value=false;termForm.term='';await loadTerms()}finally{saving.value=false}}
async function remove(row){await ElMessageBox.confirm(`删除术语 ${row.term}？`,'删除术语',{type:'warning'});await deleteTerm(row.id);await loadTerms()}
function editMetric(row){Object.keys(metricForm).forEach(k=>delete metricForm[k]);Object.assign(metricForm,row);metricVisible.value=true}
async function saveMetric(){if(!metricForm.name?.trim()){ElMessage.warning('请填写指标名称');return}saving.value=true;try{await updateMetric({...metricForm,dsCode:metricForm.dsCode||null,probeSql:metricForm.probeSql||null});metricVisible.value=false;metrics.value=await listMetrics();ElMessage.success('指标口径已保存')}finally{saving.value=false}}
async function evaluate(row){evaluating.value=row.metricCode;try{const result=await evaluateMetric(row.metricCode);values.value={...values.value,[row.metricCode]:result};ElMessage[result.alarm?'warning':'success'](result.value==null?'源数据未返回数值':`本次实测：${result.value}`)}finally{evaluating.value=''}}
onMounted(async()=>{await concepts.fetchAll();await Promise.all([loadTerms(),listMetrics().then(x=>{metrics.value=x}),listDatasources().then(x=>{datasources.value=x})])})
</script>
<style scoped>.dictionary{margin-top:18px}.toolbar{display:flex;gap:12px;margin:12px 0 18px}.toolbar .el-input{max-width:650px}.toolbar .el-select{width:260px}.metrics{margin-top:16px}</style>
